from collections import deque

def get_connected_component(grid, start_pos, background=0):
    """Find all connected cells of same 'foreground' value from start"""
    h, w = len(grid), len(grid[0])
    sr, sc = start_pos

    # First check if start position has foreground value
    val = grid[sr][sc]
    if val == background:
        return set()

    queue = deque([(sr, sc)])
    visited = {(sr, sc)}

    while queue:
        r, c = queue.popleft()

        for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < h and 0 <= nc < w:
                if (nr, nc) not in visited and grid[nr][nc] != background:
                    visited.add((nr, nc))
                    queue.append((nr, nc))

    return visited

